const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-image-description-backfill", node: "Code: Log Still Failed (Ollama Error)" } });
const staticData = $getWorkflowStaticData('node');
